import { IValueAnimator } from "soui4/IValueAnimator";
import { IAnimatorSet } from "soui4/IAnimatorSet";
import { AnimatorSetPlayMode } from "soui4/IAnimatorSet";
import { SValueAnimator } from "soui4/SValueAnimator";



/**
 * Interface for animator set
 */
export interface SAnimatorSet extends SValueAnimator {
    /** Get the underlying IAnimatorSet object */
    getIAnimatorSet(): IAnimatorSet;

    /** Add animator to the set */
    addAnimator(animator: IValueAnimator): void;

    /** Add animator after another animator */
    addAnimatorAfter(animator: IValueAnimator, afterAnimator: IValueAnimator): void;

    /** Add animator with another animator (parallel) */
    addAnimatorWith(animator: IValueAnimator, withAnimator: IValueAnimator): void;

    /** Remove animator from the set */
    removeAnimator(animator: IValueAnimator): void;

    /** Remove all animators from the set */
    removeAllAnimators(): void;

    /** Get animator count */
    getAnimatorCount(): number;

    /** Get animator at specified index */
    getAnimatorAt(index: number): IValueAnimator;

    /** Set play mode */
    setPlayMode(mode: AnimatorSetPlayMode): void;

    /** Get play mode */
    getPlayMode(): AnimatorSetPlayMode;
}
